$ErrorActionPreference = 'Stop'
$repoUrl = 'https://github.com/Ibro4798/NaijaDrops.git'
$work = Join-Path $PSScriptRoot 'NaijaDrops_fix_msg_customer'
if (Test-Path -LiteralPath $work) { Remove-Item -LiteralPath $work -Recurse -Force }
git clone --depth 1 -c core.autocrlf=false $repoUrl $work
Set-Location -LiteralPath $work

$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$errors = New-Object System.Collections.Generic.List[string]

function Backup-File([string]$path) {
    $bak = "$path.bak_$stamp"
    Copy-Item -LiteralPath $path -Destination $bak -Force
}

function Patch-File([string]$relPath, [string]$oldB64, [string]$newB64, [string]$desc) {
    $path = Join-Path $work $relPath
    if (-not (Test-Path -LiteralPath $path)) {
        $errors.Add("NOT FOUND: $relPath ($desc)")
        return
    }
    $old = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($oldB64))
    $new = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($newB64))
    $content = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
    $count = ([regex]::Matches($content, [regex]::Escape($old))).Count
    if ($count -ne 1) {
        $errors.Add("ANCHOR MISMATCH ($count matches, expected 1): $relPath :: $desc")
        return
    }
    Backup-File $path
    $idx = $content.IndexOf($old)
    $updated = $content.Substring(0, $idx) + $new + $content.Substring($idx + $old.Length)
    $utf8Bom = New-Object System.Text.UTF8Encoding($true)
    [System.IO.File]::WriteAllText($path, $updated, $utf8Bom)
    Write-Host "[OK] Patched $relPath :: $desc" -ForegroundColor Green
}

function New-CodeFile([string]$relPath, [string]$contentB64, [string]$desc) {
    $path = Join-Path $work $relPath
    if (Test-Path -LiteralPath $path) {
        $errors.Add("ALREADY EXISTS: $relPath ($desc)")
        return
    }
    $dir = Split-Path -Path $path -Parent
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($contentB64))
    $utf8Bom = New-Object System.Text.UTF8Encoding($true)
    [System.IO.File]::WriteAllText($path, $content, $utf8Bom)
    Write-Host "[OK] Created $relPath :: $desc" -ForegroundColor Green
}

